-- GENERATED by tools/mirror-checks/dn-reflection-questions.mjs (edit there). Kind "module"; money questions "financial".

insert into mirror.question_sets (key, kind, title, intro, sort)
select v.key, 'module', v.title, v.intro, v.sort from (values
  ('dn_today', 'What does my life cost today?', 'The real cost of your life now, including what someone else pays or what assistance covers.', 101),
  ('dn_resources', 'What resources do I have today?', 'Cash income, benefits, help that isn''t cash, and the people you can turn to.', 102),
  ('dn_gap', 'What is my financial gap?', 'The difference between what life costs and what you have.', 103),
  ('dn_stable', 'What would a stable life cost me?', 'Your preferred, sustainable way of living, and what it would take.', 104),
  ('dn_want', 'What kind of life do I want to afford?', 'Learning, family, interests, savings and the things that make life yours.', 105),
  ('dn_generate', 'How will I generate my Daily Number?', 'Work, training, your own business, benefits and other ways to meet your Daily Number. You don''t have to earn every dollar: housing help, coverage and community support all count.', 106)
) v(key, title, intro, sort)
on conflict (key) do nothing;

